public class ChannelThresholderTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String pixel(java.awt.image.BufferedImage img, int x, int y) {
        if (img == null) {
            return "null-image";
        }
        if (x < 0 || y < 0 || x >= img.getWidth() || y >= img.getHeight()) {
            return "out-of-range";
        }
        return String.format("#%06X", img.getRGB(x, y) & 0xFFFFFF);
    }

    static int widthOf(java.awt.image.BufferedImage img) {
        return img == null ? -1 : img.getWidth();
    }

    static int heightOf(java.awt.image.BufferedImage img) {
        return img == null ? -1 : img.getHeight();
    }

    static java.awt.image.BufferedImage sample() {
        int[][] colors = {
                { 0xC8000A, 0x102080, 0xFFFFFF },
                { 0x808080, 0x00FF00, 0x7F7F7F },
                { 0xFF2080, 0x000000, 0xC0C0C0 }
        };
        java.awt.image.BufferedImage img = new java.awt.image.BufferedImage(
                3, 3, java.awt.image.BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < 3; y++) {
            for (int x = 0; x < 3; x++) {
                img.setRGB(x, y, colors[y][x]);
            }
        }
        return img;
    }

    public static void main(String[] args) {
        try {
            java.awt.image.BufferedImage src = sample();
            java.awt.image.BufferedImage t = ChannelThresholder.threshold(src, 127);
            java.awt.image.BufferedImage strict = ChannelThresholder.threshold(src, 254);
            check("bright red channel only (0,0)", "#FF0000", pixel(t, 0, 0));
            check("only blue is above the limit (1,0)", "#0000FF", pixel(t, 1, 0));
            check("white stays white (2,0)", "#FFFFFF", pixel(t, 2, 0));
            check("128 is above 127 (0,1)", "#FFFFFF", pixel(t, 0, 1));
            check("127 is not above 127 (2,1)", "#000000", pixel(t, 2, 1));
            check("mixed channels stay mixed (0,2)", "#FF00FF", pixel(t, 0, 2));
            check("white pixels after threshold 127", 3, ChannelThresholder.countPure(t));
            check("white pixels after threshold 254", 1, ChannelThresholder.countPure(strict));
            check("source is untouched at (0,0)", "#C8000A", pixel(src, 0, 0));
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
